      district: 'Ranchi',
      family_income_annual: 110000,
      occupation: 'Daily Wage Artisan',
      ration_card_status: 'BPL',
      gender: 'male',
      diagnosis: 'Pulmonary Tuberculosis (Sputum Positive)',
      treatment_required: 'DOTS Regimen Therapy & Monthly Nutrition DBT',
