          label: 'Facility Dashboard',
          shortLabel: 'Dashboard',
          description: 'Multi-source facility operations, live queue & resource control',
          badge: 'Operations',
          badgeClass: 'bg-emerald-50 text-emerald-700 border-emerald-200'
